UPDATE clients SET notes = '{"sentinel":"__client_meta__","_meta":{"domainExpiry":"2025-10-23","hostingExpiry":"2026-10-23"},"text":"","blocks":[{"type":"heading2","text":"✅ LISTE DE TÂCHES ÉQUIPE — GOOGLE MAPS #1"},{"type":"paragraph","text":"\"Location de Voiture Rabat\""},{"type":"heading2","text":"👥 ORGANISATION DES RÔLES"},{"type":"paragraph","text":"RôleQui fait quoi🧑‍💼 Manager / ResponsableGBP, stratégie, citations, suivi KPI📸 Photo / VidéoPhotos flotte, agence, équipe, vidéos💬 Chargé Avis / Relation ClientDemandes d''avis, réponses, WhatsApp🌐 Web / Réseaux SociauxSite web, Instagram, TikTok, Facebook"},{"type":"heading2","text":"🔴 SEMAINE 1 — TÂCHES CRITIQUES (Jours 1 à 7)"},{"type":"heading2","text":"🧑‍💼 MANAGER — À FAIRE EN PRIORITÉ ABSOLUE"},{"type":"heading2","text":"GBP — CONFIGURATION DE BASE"},{"type":"checklist","items":["Ouvrir Google Business Profile Manager","Vérifier que le nom = nom légal exact de l''agence","Catégorie principale → \"Car rental agency\"","Ajouter 5 catégories secondaires : - Luxury car rental agency - Van rental agency - Airport transportation service - Car leasing service - Chauffeur driven car rental service","Écrire la description (750 caractères max) → Inclure : \"sans carte bancaire\", \"livraison aéroport\", \"WhatsApp\", \"Rabat\", \"24h/24\"","Ajouter lien WhatsApp dans \"Lien de réservation\" → Format : https://wa.me/212XXXXXXXXX","Ajouter lien site web","Zones desservies → Rabat, Salé, Témara, Kénitra, Aéroport Rabat-Salé","Confirmer les horaires (bouton \"Confirmer\")","Ajouter adresse exacte (identique à tout le reste)","Ajouter numéro de téléphone"]},{"type":"heading2","text":"DOCUMENT NAP MAÎTRE (à créer ce jour)"},{"type":"checklist","items":["Nom exact : ___________________________","Adresse complète : _____________________","Téléphone : ___________________________","Site web : _____________________________",""]},{"type":"paragraph","text":"→ Ce document = référence pour TOUTE inscription future"},{"type":"heading2","text":"📸 PHOTO/VIDÉO — SHOOTING URGENT"},{"type":"heading2","text":"PHOTOS À FAIRE CETTE SEMAINE (objectif 80 photos)"},{"type":"checklist","items":["Extérieur agence — façade de face (4 photos)","Extérieur agence — nuit avec éclairage (2 photos)","Intérieur — bureau d''accueil (3 photos)","Intérieur — salle d''attente (2 photos)","Équipe complète — photo de groupe (1 photo)","Chaque membre de l''équipe — photo individuelle","Logo de l''agence sur fond blanc (1 photo)"]},{"type":"heading2","text":"PHOTOS FLOTTE (5 angles par véhicule)"},{"type":"checklist","items":["Face avant","Face arrière","Profil gauche","Intérieur / sièges","Tableau de bord"]},{"type":"paragraph","text":"→ Répéter pour CHAQUE véhicule de la flotte"},{"type":"heading2","text":"PHOTOS CONTEXTE RABAT"},{"type":"checklist","items":["Véhicule devant un monument de Rabat","Livraison d''un véhicule à un client (avec accord)","Remise des clés"]},{"type":"heading2","text":"VIDÉO (priorité haute)"},{"type":"checklist","items":["Filmer visite agence 30 secondes","Filmer showcase flotte 30 secondes","Uploader les 2 vidéos sur GBP"]},{"type":"heading2","text":"💬 CHARGÉ AVIS — DÉMARRAGE IMMÉDIAT"},{"type":"heading2","text":"MISE EN PLACE DU SYSTÈME D''AVIS"},{"type":"checklist","items":["Générer le lien d''avis Google depuis GBP → GBP Dashboard → Accueil → \"Obtenir plus d''avis\"","Créer QR code (sur qr-code-generator.com)","Imprimer le QR code sur : - Contrat de location - Facture / reçu client - Autocollant tableau de bord de chaque voiture - Bureau d''accueil (panneau visible)"]},{"type":"heading2","text":"MESSAGE WHATSAPP DE DEMANDE D''AVIS"},{"type":"checklist","items":["Copier ce modèle et l''enregistrer :"]},{"type":"paragraph","text":"\"Bonjour [Prénom] 😊 Merci d''avoir choisi [Votre Marque] ! Si votre location s''est bien passée, un avis Google nous aiderait beaucoup — 30 secondes seulement 🙏"},{"type":"heading2","text":"👉 [VOTRE LIEN AVIS]"},{"type":"paragraph","text":"Merci et à bientôt !\""},{"type":"checklist","items":["Envoyer ce message aux 20-30 derniers clients satisfaits","Répondre à TOUS les anciens avis (avec mots-clés)"]},{"type":"heading2","text":"MODÈLE DE RÉPONSE AVIS POSITIF"},{"type":"checklist","items":["Copier ce modèle :"]},{"type":"paragraph","text":"\"Merci [Prénom] pour votre avis ⭐ ! Nous sommes ravis que votre expérience de location de voiture à Rabat chez [Marque] ait été excellente. Notre équipe reste disponible 24h/24 pour votre prochaine location. À très bientôt ! 🚗\""},{"type":"heading2","text":"MODÈLE DE RÉPONSE AVIS NÉGATIF"},{"type":"checklist","items":["Copier ce modèle :"]},{"type":"paragraph","text":"\"Bonjour [Prénom], merci pour votre retour. Nous sommes désolés de cette expérience. Contactez-nous au [WhatsApp] pour qu''on règle ça ensemble. Cordialement, [Marque]\""},{"type":"heading2","text":"🌐 WEB / RÉSEAUX SOCIAUX — CRÉATION COMPTES"},{"type":"heading2","text":"RÉSEAUX SOCIAUX À CRÉER / OPTIMISER"},{"type":"checklist","items":["Instagram → créer compte @[votrenomcommercial] - Photo profil = logo - Bio = \"Location de voiture à Rabat 🚗 Sans carte bancaire | Livraison 24h/24 📍 Rabat, Salé, Témara 👇 Réserver sur WhatsApp\" - Lien dans bio = lien WhatsApp - Publier 6 premières photos (3 véhicules + 3 agence)"]},{"type":"checklist","items":["TikTok → créer compte - Même bio qu''Instagram - Filmer 1ère vidéo : \"Comment louer une voiture chez [Marque] en 2 minutes sur WhatsApp\""]},{"type":"checklist","items":["Facebook Page Business → créer / optimiser - Nom = NOM MAÎTRE EXACT - Adresse = ADRESSE MAÎTRE EXACTE - Téléph TÉLÉPHONE MAÎTRE EXACT - Catégorie = Location de voitures"]},{"type":"checklist","items":["Lier tous les comptes au GBP (GBP → Modifier le profil → Ajouter les liens sociaux)"]},{"type":"heading2","text":"🟠 SEMAINE 2-4 — TÂCHES DES 30 PREMIERS JOURS"},{"type":"heading2","text":"🧑‍💼 MANAGER"},{"type":"heading2","text":"GBP — CONTENU AVANCÉ"},{"type":"checklist","items":["Ajouter 10 services avec descript